import struct

with open("{TARGET}", "rb") as f:
    data = f.read()

def va_to_offset(va):
    return va - 0x401000

inst_offset = va_to_offset(0x404180)
expected_offset = va_to_offset(0x4040a0)

instructions = []
for i in range(800):
    try:
        val = struct.unpack('<Q', data[inst_offset + i*8 : inst_offset + i*8 + 8])[0]
        instructions.append(val)
    except:
        break

expected = []
for i in range(8):
    val = struct.unpack('<Q', data[expected_offset + i*8 : expected_offset + i*8 + 8])[0]
    expected.append(val)

print(f"Read {len(instructions)} instructions")

# Parse through with bounds checking
ip = 0
current_block = []
blocks = []

while ip < len(instructions):
    inst = instructions[ip]
    opcode = inst % 19

    if opcode == 0:  # load immediate
        if ip + 1 < len(instructions):
            imm = instructions[ip + 1]
            current_block.append(('LOAD_IMM', imm))
            ip += 2
        else:
            break
    elif opcode == 12:
        if ip + 1 < len(instructions):
            idx = instructions[ip + 1]
            current_block.append(('LOAD_REG', idx))
            ip += 2
        else:
            break
    elif opcode == 18:
        current_block.append(('HALT', None))
        blocks.append(current_block)
        break
    elif opcode == 2:
        current_block.append(('ADD', None))
        ip += 1
    elif opcode == 3:
        current_block.append(('SUB', None))
        ip += 1
    elif opcode == 4:
        current_block.append(('MUL', None))
        ip += 1
    elif opcode == 5:
        current_block.append(('AND', None))
        ip += 1
    elif opcode == 6:
        current_block.append(('XOR', None))
        ip += 1
    elif opcode == 7:
        current_block.append(('OR', None))
        ip += 1
    elif opcode == 8:
        current_block.append(('SHL', None))
        ip += 1
    elif opcode == 9:
        current_block.append(('SHR', None))
        ip += 1
    elif opcode == 10:
        current_block.append(('STORE_LOCAL', None))
        ip += 1
    elif opcode == 11:
        current_block.append(('SWAP', None))
        ip += 1
    elif opcode == 13:
        current_block.append(('LOAD_INPUT', None))
        ip += 1
    elif opcode == 14:
        current_block.append(('STORE_INPUT', None))
        blocks.append(current_block)
        current_block = []
        ip += 1
    elif opcode == 15:
        current_block.append(('CMP', None))
        ip += 1
    elif opcode == 16:
        current_block.append(('COND16', None))
        ip += 1
    elif opcode == 17:
        current_block.append(('COND17', None))
        ip += 1
    elif opcode == 1:
        current_block.append(('THROW', None))
        ip += 1
    else:
        current_block.append(('UNK', opcode))
        ip += 1

print(f"Found {len(blocks)} transformation blocks")

# Show the blocks
for i, block in enumerate(blocks):
    print(f"\n=== Block {i} ===")
    for op, val in block:
        if val is not None:
            print(f"  {op}: {hex(val)}")
        else:
            print(f"  {op}")
    if len(block) > 30:
        print("  ... (truncated)")
